//===- mac_sparse.cc --------------------------------------------*- C++ -*-===//
//
// conf capture kernel for sparse MAC config mode (0, 0, 1) `4x32_32x8`
// (GENERATED by tools/gen_mac_sparse.py). Per tile and signedness flavour it builds the sparse B operand with update() from a stored-data block and a mask block,
// then runs mul, mul, mulc_sm, mac_z, mac_sh, mac_sm, mac_sa, mac_sm_sa, addmac_z, addmac_sa2, addmac_all.
// Chunk layout: 9 operand blocks of T tiles (A0 D0 M0 A1 D1 M1 A2 D2 M2).
//
//===----------------------------------------------------------------------===//

#include <stdint.h>

// Peano builds see no Chess-side define; the stream/ADF half of aie_api is not needed.
#ifndef __AIE_API_AIE_ADF_HPP__
#define __AIE_API_AIE_ADF_HPP__
#endif
#include <aie_api/aie.hpp>

#define T 2
#define OUT_WORDS_PER_TILE 1408

#define STORE(r, dst) \
  do { aie::accum<acc32, 32> w(r); aie::store_v((dst), w.to_vector<int32>(0)); } while (0)

extern "C" {

void mac_sparse(uint8_t *restrict in, int32_t *restrict out) {
  uint8_t *in0 = in + 0;
  uint8_t *in1 = in + 0 + T * 128;
  uint8_t *in2 = in + 0 + T * 128 + T * 64;
  uint8_t *in3 = in + 0 + T * 128 + T * 64 + T * 16;
  uint8_t *in4 = in + 0 + T * 128 + T * 64 + T * 16 + T * 128;
  uint8_t *in5 = in + 0 + T * 128 + T * 64 + T * 16 + T * 128 + T * 64;
  uint8_t *in6 = in + 0 + T * 128 + T * 64 + T * 16 + T * 128 + T * 64 + T * 16;
  uint8_t *in7 = in + 0 + T * 128 + T * 64 + T * 16 + T * 128 + T * 64 + T * 16 + T * 128;
  uint8_t *in8 = in + 0 + T * 128 + T * 64 + T * 16 + T * 128 + T * 64 + T * 16 + T * 128 + T * 64;
  event0();
  for (int n = 0; n < T; n++) {
    int32_t *o = out + n * OUT_WORDS_PER_TILE;
    { // ss
      v128int8 a0 = *(v128int8 *)(in0 + n * 128);
      v128int4 d0 = *(v128int4 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v256int4_sparse b0;
      b0.data = d0;
      b0.mask = m0;
      v128int8 a1 = *(v128int8 *)(in3 + n * 128);
      v128int4 d1 = *(v128int4 *)(in4 + n * 64);
      sparsity_t m1 = *(sparsity_t *)(in5 + n * 16);
      v256int4_sparse b1;
      b1.data = d1;
      b1.mask = m1;
      v128int8 a2 = *(v128int8 *)(in6 + n * 128);
      v128int4 d2 = *(v128int4 *)(in7 + n * 64);
      sparsity_t m2 = *(sparsity_t *)(in8 + n * 16);
      v256int4_sparse b2;
      b2.data = d2;
      b2.mask = m2;
      v32acc32 r0 = mul_4x32_32x8(a0, b0);
      v32acc32 r1 = mul_4x32_32x8(a1, b1);
      v32acc32 r2 = mul_4x32_32x8_conf(a2, b2, 1);
      v32acc32 r3 = mac_4x32_32x8_conf(a2, b2, r0, 1, 0, 0, 0);
      v32acc32 r4 = mac_4x32_32x8_conf(a2, b2, r0, 0, 1, 0, 0);
      v32acc32 r5 = mac_4x32_32x8_conf(a2, b2, r0, 0, 0, 1, 0);
      v32acc32 r6 = mac_4x32_32x8_conf(a2, b2, r0, 0, 0, 0, 1);
      v32acc32 r7 = mac_4x32_32x8_conf(a2, b2, r0, 0, 0, 1, 1);
      v32acc32 r8 = addmac_4x32_32x8_conf(a2, b2, r0, r1, 1, 0, 0, 0, 0);
      v32acc32 r9 = addmac_4x32_32x8_conf(a2, b2, r0, r1, 0, 0, 0, 0, 1);
      v32acc32 r10 = addmac_4x32_32x8_conf(a2, b2, r0, r1, 0, 0, 1, 1, 1);
      STORE(r0, o + 0);
      STORE(r1, o + 32);
      STORE(r2, o + 64);
      STORE(r3, o + 96);
      STORE(r4, o + 128);
      STORE(r5, o + 160);
      STORE(r6, o + 192);
      STORE(r7, o + 224);
      STORE(r8, o + 256);
      STORE(r9, o + 288);
      STORE(r10, o + 320);
    }
    { // su
      v128int8 a0 = *(v128int8 *)(in0 + n * 128);
      v128uint4 d0 = *(v128uint4 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v256uint4_sparse b0;
      b0.data = d0;
      b0.mask = m0;
      v128int8 a1 = *(v128int8 *)(in3 + n * 128);
      v128uint4 d1 = *(v128uint4 *)(in4 + n * 64);
      sparsity_t m1 = *(sparsity_t *)(in5 + n * 16);
      v256uint4_sparse b1;
      b1.data = d1;
      b1.mask = m1;
      v128int8 a2 = *(v128int8 *)(in6 + n * 128);
      v128uint4 d2 = *(v128uint4 *)(in7 + n * 64);
      sparsity_t m2 = *(sparsity_t *)(in8 + n * 16);
      v256uint4_sparse b2;
      b2.data = d2;
      b2.mask = m2;
      v32acc32 r0 = mul_4x32_32x8(a0, b0);
      v32acc32 r1 = mul_4x32_32x8(a1, b1);
      v32acc32 r2 = mul_4x32_32x8_conf(a2, b2, 1);
      v32acc32 r3 = mac_4x32_32x8_conf(a2, b2, r0, 1, 0, 0, 0);
      v32acc32 r4 = mac_4x32_32x8_conf(a2, b2, r0, 0, 1, 0, 0);
      v32acc32 r5 = mac_4x32_32x8_conf(a2, b2, r0, 0, 0, 1, 0);
      v32acc32 r6 = mac_4x32_32x8_conf(a2, b2, r0, 0, 0, 0, 1);
      v32acc32 r7 = mac_4x32_32x8_conf(a2, b2, r0, 0, 0, 1, 1);
      v32acc32 r8 = addmac_4x32_32x8_conf(a2, b2, r0, r1, 1, 0, 0, 0, 0);
      v32acc32 r9 = addmac_4x32_32x8_conf(a2, b2, r0, r1, 0, 0, 0, 0, 1);
      v32acc32 r10 = addmac_4x32_32x8_conf(a2, b2, r0, r1, 0, 0, 1, 1, 1);
      STORE(r0, o + 352);
      STORE(r1, o + 384);
      STORE(r2, o + 416);
      STORE(r3, o + 448);
      STORE(r4, o + 480);
      STORE(r5, o + 512);
      STORE(r6, o + 544);
      STORE(r7, o + 576);
      STORE(r8, o + 608);
      STORE(r9, o + 640);
      STORE(r10, o + 672);
    }
    { // us
      v128uint8 a0 = *(v128uint8 *)(in0 + n * 128);
      v128int4 d0 = *(v128int4 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v256int4_sparse b0;
      b0.data = d0;
      b0.mask = m0;
      v128uint8 a1 = *(v128uint8 *)(in3 + n * 128);
      v128int4 d1 = *(v128int4 *)(in4 + n * 64);
      sparsity_t m1 = *(sparsity_t *)(in5 + n * 16);
      v256int4_sparse b1;
      b1.data = d1;
      b1.mask = m1;
      v128uint8 a2 = *(v128uint8 *)(in6 + n * 128);
      v128int4 d2 = *(v128int4 *)(in7 + n * 64);
      sparsity_t m2 = *(sparsity_t *)(in8 + n * 16);
      v256int4_sparse b2;
      b2.data = d2;
      b2.mask = m2;
      v32acc32 r0 = mul_4x32_32x8(a0, b0);
      v32acc32 r1 = mul_4x32_32x8(a1, b1);
      v32acc32 r2 = mul_4x32_32x8_conf(a2, b2, 1);
      v32acc32 r3 = mac_4x32_32x8_conf(a2, b2, r0, 1, 0, 0, 0);
      v32acc32 r4 = mac_4x32_32x8_conf(a2, b2, r0, 0, 1, 0, 0);
      v32acc32 r5 = mac_4x32_32x8_conf(a2, b2, r0, 0, 0, 1, 0);
      v32acc32 r6 = mac_4x32_32x8_conf(a2, b2, r0, 0, 0, 0, 1);
      v32acc32 r7 = mac_4x32_32x8_conf(a2, b2, r0, 0, 0, 1, 1);
      v32acc32 r8 = addmac_4x32_32x8_conf(a2, b2, r0, r1, 1, 0, 0, 0, 0);
      v32acc32 r9 = addmac_4x32_32x8_conf(a2, b2, r0, r1, 0, 0, 0, 0, 1);
      v32acc32 r10 = addmac_4x32_32x8_conf(a2, b2, r0, r1, 0, 0, 1, 1, 1);
      STORE(r0, o + 704);
      STORE(r1, o + 736);
      STORE(r2, o + 768);
      STORE(r3, o + 800);
      STORE(r4, o + 832);
      STORE(r5, o + 864);
      STORE(r6, o + 896);
      STORE(r7, o + 928);
      STORE(r8, o + 960);
      STORE(r9, o + 992);
      STORE(r10, o + 1024);
    }
    { // uu
      v128uint8 a0 = *(v128uint8 *)(in0 + n * 128);
      v128uint4 d0 = *(v128uint4 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v256uint4_sparse b0;
      b0.data = d0;
      b0.mask = m0;
      v128uint8 a1 = *(v128uint8 *)(in3 + n * 128);
      v128uint4 d1 = *(v128uint4 *)(in4 + n * 64);
      sparsity_t m1 = *(sparsity_t *)(in5 + n * 16);
      v256uint4_sparse b1;
      b1.data = d1;
      b1.mask = m1;
      v128uint8 a2 = *(v128uint8 *)(in6 + n * 128);
      v128uint4 d2 = *(v128uint4 *)(in7 + n * 64);
      sparsity_t m2 = *(sparsity_t *)(in8 + n * 16);
      v256uint4_sparse b2;
      b2.data = d2;
      b2.mask = m2;
      v32acc32 r0 = mul_4x32_32x8(a0, b0);
      v32acc32 r1 = mul_4x32_32x8(a1, b1);
      v32acc32 r2 = mul_4x32_32x8_conf(a2, b2, 1);
      v32acc32 r3 = mac_4x32_32x8_conf(a2, b2, r0, 1, 0, 0, 0);
      v32acc32 r4 = mac_4x32_32x8_conf(a2, b2, r0, 0, 1, 0, 0);
      v32acc32 r5 = mac_4x32_32x8_conf(a2, b2, r0, 0, 0, 1, 0);
      v32acc32 r6 = mac_4x32_32x8_conf(a2, b2, r0, 0, 0, 0, 1);
      v32acc32 r7 = mac_4x32_32x8_conf(a2, b2, r0, 0, 0, 1, 1);
      v32acc32 r8 = addmac_4x32_32x8_conf(a2, b2, r0, r1, 1, 0, 0, 0, 0);
      v32acc32 r9 = addmac_4x32_32x8_conf(a2, b2, r0, r1, 0, 0, 0, 0, 1);
      v32acc32 r10 = addmac_4x32_32x8_conf(a2, b2, r0, r1, 0, 0, 1, 1, 1);
      STORE(r0, o + 1056);
      STORE(r1, o + 1088);
      STORE(r2, o + 1120);
      STORE(r3, o + 1152);
      STORE(r4, o + 1184);
      STORE(r5, o + 1216);
      STORE(r6, o + 1248);
      STORE(r7, o + 1280);
      STORE(r8, o + 1312);
      STORE(r9, o + 1344);
      STORE(r10, o + 1376);
    }
  }
  event1();
}

} // extern "C"
